for suf, dsl in V:
    ids = [i for i in qs if i.startswith("q_" + suf)]
    assert len(ids) == 1, (suf, ids)
    i = ids[0]
    assert i not in ev, ("thuoc eval300", i)
    out.append({"id": i, "question": qs[i]["question"], "dsl": dsl})
p = os.path.join(os.path.dirname(__file__), "vi_du_tay.jsonl")
with open(p, "w", encoding="utf-8") as f:
    for r in out:
        f.write(json.dumps(r, ensure_ascii=False) + "\n")
print(len(out), "vi du ->", p)
